1	package vault
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"syscall"
15		"time"
16	)
17	
18	type Entry struct {
19		Name      string    `json:"name"`
20		Digest    string    `json:"digest"`
21		Size      int64     `json:"size"`
22		CreatedAt time.Time `json:"createdAt"`
23	}
24	
25	type index struct {
26		Entries map[string]Entry `json:"entries"`
27	}
28	
29	type Store struct{ root string }
30	
31	func New(root string) *Store { return &Store{root: root} }
32	
33	// withLock serializes access to the repository across cooperating processes.
34	// Mutating operations pass exclusive=true; readers take a shared lock. The
35	// lock is an flock on <root>/.lock, so it is released automatically if a
36	// process dies mid-operation and nothing can wait forever on a stale lock.
37	func (s *Store) withLock(exclusive bool, fn func() error) error {
38		return s.withLockOpts(exclusive, true, fn)
39	}
40	
41	// withLockOpts is withLock with control over root creation. Read-only-style
42	// operations that must never materialize a missing repository (such as
43	// export) pass createRoot=false.
44	func (s *Store) withLockOpts(exclusive, createRoot bool, fn func() error) error {
45		if strings.TrimSpace(s.root) == "" {
46			return errors.New("root is required")
47		}
48		if createRoot {
49			if err := os.MkdirAll(s.root, 0o755); err != nil {
50				return err
51			}
52		}
53		// Read-only operations that must not materialize anything open the lock
54		// without O_CREATE: an initialized repository always has a lock file, so
55		// a missing one means the repository was never initialized.
56		var lock *os.File
57		var err error
58		if createRoot {
59			lock, err = os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o644)
60		} else {
61			lock, err = os.OpenFile(s.lockPath(), os.O_RDWR, 0o644)
62		}
63		if err != nil {
64			if !createRoot && errors.Is(err, os.ErrNotExist) {
65				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
66			}
67			return err
68		}
69		defer lock.Close()
70		mode := syscall.LOCK_SH
71		if exclusive {
72			mode = syscall.LOCK_EX
73		}
74		if err := syscall.Flock(int(lock.Fd()), mode); err != nil {
75			return err
76		}
77		defer syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
78		return fn()
79	}
80	
81	func (s *Store) Init() error {
82		return s.withLock(true, s.initLocked)
83	}
84	
85	func (s *Store) initLocked() error {
86		if err := os.MkdirAll(filepath.Join(s.root, "objects"), 0o755); err != nil {
87			return err
88		}
89		_, err := os.Stat(s.indexPath())
90		if errors.Is(err, os.ErrNotExist) {
91			return s.save(index{Entries: map[string]Entry{}})
92		}
93		return err
94	}
95	
96	// Put stores the content of source under name. The content is staged in a
97	// temporary file inside the repository while its size and SHA-256 are
98	// computed, then either installed as a new content object or matched against
99	// the object already stored under the same digest. A successful put means the
100	// object behind name's digest is verifiably complete: an existing object is
101	// reused only when it is a regular file whose full contents can be read and
102	// whose actual size and SHA-256 equal this upload's. Anything else — a
103	// truncated or rewritten object, a same-size object with different bytes, a
104	// symlink (followed or dangling), a directory, or an unreadable path — fails
105	// the upload and leaves the name mapping, the existing object, and every
106	// snapshot untouched; a damaged object is never repaired by overwriting it.
107	// Reuse never copies, rewrites, or re-permissions the healthy object, so
108	// several names can share one object.
109	//
110	// Adding a name and overwriting one both presuppose the whole current name
111	// mapping: before the input is even read, the index must be one complete JSON
112	// object with an explicitly present entries mapping under the same strict
113	// rules verify and snapshot creation enforce (a genuine {"entries":{}} is a
114	// legitimate empty repository; a bare null, a missing or null entries
115	// mapping, a non-object mapping, truncated input or trailing content, and any
116	// duplicate key at any level — including a name written directly and again
117	// through Unicode escapes — is corruption), and every existing record must be
118	// keyed by its recorded name with a legal name, a 64-character
119	// lowercase-hex digest, and a non-negative size. One bad record rejects the
120	// entire upload even when it is unrelated to this upload's name; the mapping
121	// is never treated as empty, filtered, or rewritten. On such a failure the
122	// index's original bytes, every snapshot, and all content objects stay in
123	// place, no object for this upload's digest is added, and no staged temporary
124	// file remains. Index errors name both the upload and the index problem
125	// ("cannot store <name>: current index is corrupt: …", naming the duplicated
126	// key or offending artifact), with an index that cannot be read reported
127	// distinctly from an input file that cannot be read and from a damaged
128	// content object.
129	func (s *Store) Put(name, source string) (Entry, error) {
130		if err := validateName(name); err != nil {
131			return Entry{}, err
132		}
133		if source == "" {
134			return Entry{}, errors.New("file is required")
135		}
136		var entry Entry
137		err := s.withLock(true, func() error {
138			if err := s.initLocked(); err != nil {
139				return err
140			}
141			// Both a new name and an overwrite presuppose the whole current
142			// mapping: every existing key and record must be usable before this
143			// upload adds or replaces anything. This runs before the input is
144			// opened and before any temporary file is staged, so a corrupt or
145			// unreadable index fails the upload without a new content object, a
146			// leftover temporary file, or a rewritten mapping that drops the old
147			// artifact references.
148			idx, err := s.loadIndexForUpload(name)
149			if err != nil {
150				return err
151			}
152			in, err := os.Open(source)
153			if err != nil {
154				return fmt.Errorf("cannot store %q: cannot read input file %q: %w", name, source, err)
155			}
156			defer in.Close()
157			tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".upload-*")
158			if err != nil {
159				return err
160			}
161			tmpName := tmp.Name()
162			defer os.Remove(tmpName)
163			hash := sha256.New()
164			size, copyErr := io.Copy(io.MultiWriter(tmp, hash), in)
165			closeErr := tmp.Close()
166			if copyErr != nil {
167				return fmt.Errorf("cannot store %q: cannot read input file %q: %w", name, source, copyErr)
168			}
169			if closeErr != nil {
170				return fmt.Errorf("cannot store %q: cannot stage upload: %w", name, closeErr)
171			}
172			digest := hex.EncodeToString(hash.Sum(nil))
173			if err := s.placeObject(name, digest, size, tmpName); err != nil {
174				return err
175			}
176			entry = Entry{Name: name, Digest: digest, Size: size, CreatedAt: time.Now().UTC()}
177			idx.Entries[name] = entry
178			return s.save(idx)
179		})
180		if err != nil {
181			return Entry{}, err
182		}
183		return entry, nil
184	}
185	
186	// placeObject makes the content object for digest available in the
187	// repository. When no object exists at the digest path yet, the staged upload
188	// at tmpName is renamed into place. When something already exists there it is
189	// reused only if it proves to be a complete, intact copy of this upload (see
190	// checkReusableObject); otherwise the upload fails and the staged file is
191	// removed by the caller's deferred cleanup. An inspection failure is never
192	// treated as "object missing": only a genuine not-exist installs new content.
193	func (s *Store) placeObject(name, digest string, size int64, tmpName string) error {
194		object := s.objectPath(digest)
195		info, err := os.Lstat(object)
196		switch {
197		case errors.Is(err, os.ErrNotExist):
198			return os.Rename(tmpName, object)
199		case err != nil:
200			return fmt.Errorf("cannot store %q: cannot inspect existing object %s: %w", name, digest, err)
201		}
202		if err := checkReusableObject(info, object, digest, size); err != nil {
203			return fmt.Errorf("cannot store %q: %w", name, err)
204		}
205		return nil
206	}
207	
208	// checkReusableObject verifies that an existing content object is a complete,
209	// intact copy of the uploaded content: a regular file — never a symlink,
210	// whether or not its target exists, and never a directory or other special
211	// file — whose actual size and SHA-256 match the digest and size computed for
212	// this upload. The object is read in full; a read failure is reported, not
213	// treated as absence.
214	func checkReusableObject(info os.FileInfo, object, digest string, size int64) error {
215		if info.Mode()&os.ModeSymlink != 0 {
216			return fmt.Errorf("existing object %s is a symbolic link", digest)
217		}
218		if !info.Mode().IsRegular() {
219			return fmt.Errorf("existing object %s is not a regular file", digest)
220		}
221		file, err := os.Open(object)
222		if err != nil {
223			return fmt.Errorf("cannot read existing object %s: %w", digest, err)
224		}
225		hash := sha256.New()
226		n, copyErr := io.Copy(hash, file)
227		closeErr := file.Close()
228		if copyErr != nil {
229			return fmt.Errorf("cannot read existing object %s: %w", digest, copyErr)
230		}
231		if closeErr != nil {
232			return fmt.Errorf("cannot read existing object %s: %w", digest, closeErr)
233		}
234		if n != size {
235			return fmt.Errorf("existing object %s is corrupted: content is %d bytes, upload is %d", digest, n, size)
236		}
237		if actual := hex.EncodeToString(hash.Sum(nil)); actual != digest {
238			return fmt.Errorf("existing object %s is corrupted: content checksum is %s", digest, actual)
239		}
240		return nil
241	}
242	
243	// loadIndexForUpload loads the current name mapping with the same strict
244	// rules verify and snapshot creation enforce, then validates every record
245	// before the upload is allowed to proceed. A genuine {"entries":{}} mapping
246	// is a healthy empty repository; anything else — a bare null, a missing or
247	// null entries mapping, a non-object mapping, a truncated document or one
248	// with trailing content, any duplicate key at any level (including a name
249	// written directly and again through Unicode escapes), or a record failing
250	// the key-matches-name / legal-name / digest / non-negative-size rules —
251	// rejects the whole upload even when the offending record is unrelated to the
252	// name being uploaded. Records are checked in sorted name order so the first
253	// bad record reported is deterministic. Every error names the upload and the
254	// index problem ("current index is corrupt" versus "current index cannot be
255	// read"), which keeps it distinct from a failure to read the upload's input
256	// file and from a damaged existing content object.
257	func (s *Store) loadIndexForUpload(uploadName string) (index, error) {
258		idx, err := s.loadStrict()
259		if err != nil {
260			return index{}, fmt.Errorf("cannot store %q: %w", uploadName, err)
261		}
262		keys := make([]string, 0, len(idx.Entries))
263		for key := range idx.Entries {
264			keys = append(keys, key)
265		}
266		sort.Strings(keys)
267		for _, key := range keys {
268			if err := validateEntryRecord(key, idx.Entries[key]); err != nil {
269				return index{}, fmt.Errorf("cannot store %q: current index is corrupt: %w", uploadName, err)
270			}
271		}
272		return idx, nil
273	}
274	
275	func (s *Store) List() ([]Entry, error) {
276		var entries []Entry
277		err := s.withLock(false, func() error {
278			idx, err := s.load()
279			if err != nil {
280				return err
281			}
282			entries = make([]Entry, 0, len(idx.Entries))
283			for _, entry := range idx.Entries {
284				entries = append(entries, entry)
285			}
286			return nil
287		})
288		if err != nil {
289			return nil, err
290		}
291		sort.Slice(entries, func(i, j int) bool { return entries[i].Name < entries[j].Name })
292		return entries, nil
293	}
294	
295	// Verify checks every entry of the current name mapping against its content
296	// object: the object must exist and its actual size and SHA-256 must match
297	// the recorded metadata. The mapping itself must be complete and unambiguous
298	// first: the index must be one complete JSON object with an explicitly
299	// present entries mapping (a true {"entries":{}} is a legitimate empty
300	// repository; null, a missing or null entries field, an array, truncated
301	// input, trailing content, or any duplicate key — including a name repeated
302	// through Unicode escapes — is corruption), and every record must pass the
303	// same validity checks downloads and gc apply (keyed by its recorded name, a
304	// legal name, a 64-character lowercase-hex digest, a non-negative size). A
305	// single malformed record fails the whole pass; bad records are never
306	// skipped to report success over the rest. Mapping problems are reported
307	// before any object is read, so index corruption is always distinguished
308	// from object damage.
309	//
310	// The whole pass — reading the mapping and checking every object it
311	// references — runs under one shared repository lock, so the mapping and the
312	// objects it points at cannot be replaced or collected by another process
313	// between the first read and the last check: an overwrite, snapshot restore,
314	// import, or gc either completes before the pass starts (and the pass
315	// observes the completed state) or waits until the pass ends. The lock is
316	// shared, so concurrent lists, downloads, and other verifies proceed
317	// alongside it. Verify never rewrites the mapping, snapshots, or objects,
318	// and never repairs damaged content; on the first failure it reports the
319	// cause and returns a zero count.
320	func (s *Store) Verify() (int, error) {
321		count := 0
322		err := s.withLock(false, func() error {
323			idx, err := s.loadStrict()
324			if err != nil {
325				return err
326			}
327			entries := make([]Entry, 0, len(idx.Entries))
328			for key, entry := range idx.Entries {
329				if err := validateEntryRecord(key, entry); err != nil {
330					return fmt.Errorf("current index is corrupt: %w", err)
331				}
332				entries = append(entries, entry)
333			}
334			// Sort by name so the first reported failure is deterministic.
335			sort.Slice(entries, func(i, j int) bool { return entries[i].Name < entries[j].Name })
336			for _, entry := range entries {
337				if err := s.verifyObject(entry); err != nil {
338					return fmt.Errorf("verify %q: %w", entry.Name, err)
339				}
340			}
341			count = len(entries)
342			return nil
343		})
344		if err != nil {
345			return 0, err
346		}
347		return count, nil
348	}
349	
350	// verifyObject checks that the content object for entry exists and that its
351	// actual size and SHA-256 match the recorded metadata.
352	func (s *Store) verifyObject(entry Entry) error {
353		file, err := os.Open(s.objectPath(entry.Digest))
354		if err != nil {
355			return err
356		}
357		hash := sha256.New()
358		size, copyErr := io.Copy(hash, file)
359		closeErr := file.Close()
360		if copyErr != nil || closeErr != nil {
361			return errors.New("read failed")
362		}
363		if size != entry.Size || hex.EncodeToString(hash.Sum(nil)) != entry.Digest {
364			return errors.New("content mismatch")
365		}
366		return nil
367	}
368	
369	func (s *Store) load() (index, error) {
370		data, err := os.ReadFile(s.indexPath())
371		if err != nil {
372			return index{}, err
373		}
374		var idx index
375		if err := json.Unmarshal(data, &idx); err != nil {
376			return index{}, err
377		}
