382	}
383	
384	func (s *Store) save(idx index) error {
385		data, err := json.MarshalIndent(idx, "", "  ")
386		if err != nil {
387			return err
388		}
389		data = append(data, '\n')
390		tmp, err := os.CreateTemp(s.root, ".index-*")
391		if err != nil {
392			return err
393		}
394		tmpName := tmp.Name()
395		defer os.Remove(tmpName)
396		if _, err := tmp.Write(data); err != nil {
397			tmp.Close()
398			return err
399		}
400		if err := tmp.Close(); err != nil {
401			return err
402		}
403		return os.Rename(tmpName, s.indexPath())
404	}
405	
406	func (s *Store) indexPath() string               { return filepath.Join(s.root, "index.json") }
407	func (s *Store) lockPath() string                { return filepath.Join(s.root, ".lock") }
408	func (s *Store) objectPath(digest string) string { return filepath.Join(s.root, "objects", digest) }
