1	package vault
2	
3	import (
4		"crypto/rand"
5		"crypto/sha256"
6		"encoding/hex"
7		"errors"
8		"fmt"
9		"io"
10		"io/fs"
11		"os"
12		"path/filepath"
13		"strings"
14		"syscall"
15		"unsafe"
16	)
17	
18	// Get downloads the artifact recorded under name in the current index to the
19	// output path. Nothing is delivered unless the stored object is complete and
20	// the destination is safe:
21	//
22	//   - the index and the selected record must be usable (parseable, with a
23	//     name mapping, the recorded name matching its key, a 64-character
24	//     lowercase-hex digest, and a non-negative size);
25	//   - the object must exist, be a regular file, and its actual size and
26	//     SHA-256 must match the record;
27	//   - the output must be outside the repository (including through a
28	//     symlinked parent), its parent directory must exist, and an existing
29	//     output must be a regular file that is not a hard link to any repository
30	//     file.
31	//
32	// The object is streamed and hashed into a temporary file beside the output;
33	// only after the complete, verified bytes are flushed is the output renamed
34	// into place. A failed download therefore leaves an existing output
35	// byte-for-byte intact and a missing output absent; an interrupted process
36	// leaves at most an unreferenced temporary file that a later download
37	// replaces without manual cleanup.
38	func (s *Store) Get(name, output string) error {
39		if err := validateName(name); err != nil {
40			return err
41		}
42		if output == "" {
43			return errors.New("output is required")
44		}
45		return s.withLock(false, func() error {
46			return s.getLocked(name, output)
47		})
48	}
49	
50	func (s *Store) getLocked(name, output string) error {
51		// The index and every record it holds must be usable before any object is
52		// read. A missing or malformed record is reported as record corruption,
53		// distinct from a name that simply does not exist.
54		idx, err := s.loadStrict()
55		if err != nil {
56			return fmt.Errorf("artifact %q: record is corrupted: %w", name, err)
57		}
58		for key, entry := range idx.Entries {
59			if err := validateEntryRecord(key, entry); err != nil {
60				return fmt.Errorf("artifact %q: record is corrupted: %w", name, err)
61			}
62		}
63		entry, ok := idx.Entries[name]
64		if !ok {
65			return fmt.Errorf("artifact %q not found", name)
66		}
67	
68		absOut, mode, pin, err := s.checkOutputSafe(output)
69		if err != nil {
70			return fmt.Errorf("artifact %q: %w", name, err)
71		}
72		defer pin.Close()
73		if err := s.downloadObject(entry, absOut, mode, pin); err != nil {
74			return fmt.Errorf("artifact %q: %w", name, err)
75		}
76		return nil
77	}
78	
79	// parentPin is an open file descriptor on the resolved directory an output is
80	// committed into. Committing through the descriptor (renameat) instead of a
81	// path means a parent directory replaced by a symlink after the check cannot
82	// redirect the final rename.
83	type parentPin struct {
84		f    *os.File
85		path string
86	}
87	
88	func (p *parentPin) Close() error {
89		if p == nil || p.f == nil {
90			return nil
91		}
92		return p.f.Close()
93	}
94	
95	// checkOutputSafe validates a destination path without opening any repository
96	// content. It returns the absolute, symlink-resolved output path, the
97	// permission bits a replacement should carry, and an open descriptor on the
98	// output's resolved parent directory used for the final atomic commit.
99	//
100	// The destination must be outside the repository:
101	//
102	//   - judged on actual locations, so neither a repository root reached
103	//     through a symlink nor a symlinked parent that leads back into the
104	//     repository can hide an inside path;
105	//   - including a path that does not exist yet, so a not-yet-created file
106	//     inside the repository is refused before anything is written;
107	//   - with every ".." in a relative path honored, while an unrelated
108	//     directory sharing a textual prefix with the repository stays allowed;
109	//
110	// its parent directory must already exist and be accessible (it is never
111	// created, though a symlinked parent resolving to a normal directory outside
112	// the repository is fine); and an existing output must be a regular file
113	// (never a symlink, including a dangling one, a directory, or another special
114	// file) that is not a hard link to any repository file — the index, the lock,
115	// any snapshot record, or any content object, including ones the current
116	// operation does not reference.
117	//
118	// Any information needed to confirm these relationships that cannot be read is
119	// reported as an error rather than assumed safe.
120	func (s *Store) checkOutputSafe(output string) (string, os.FileMode, *parentPin, error) {
121		absOut, err := filepath.Abs(output)
122		if err != nil {
123			return "", 0, nil, fmt.Errorf("output %q: cannot resolve path: %w", output, err)
124		}
125		mode := os.FileMode(0o644)
126		if info, err := os.Lstat(absOut); err == nil {
127			// Symlinks are never followed; anything that is not a regular file
128			// (directory, device, socket, ...) is refused.
129			if info.Mode()&os.ModeSymlink != 0 {
130				return "", 0, nil, fmt.Errorf("output %q is a symbolic link", output)
131			}
132			if !info.Mode().IsRegular() {
133				return "", 0, nil, fmt.Errorf("output %q is not a regular file", output)
134			}
135			mode = info.Mode().Perm()
136		} else if !errors.Is(err, os.ErrNotExist) {
137			return "", 0, nil, fmt.Errorf("output %q: cannot inspect path: %w", output, err)
138		}
139	
140		absRoot, err := filepath.Abs(s.root)
141		if err != nil {
142			return "", 0, nil, fmt.Errorf("cannot resolve repository root: %w", err)
143		}
144		resolvedRoot, err := filepath.EvalSymlinks(absRoot)
145		if err != nil {
146			return "", 0, nil, fmt.Errorf("cannot resolve repository root: %w", err)
147		}
148		// Path-based containment first: this works even when the output or its
149		// parent does not exist yet, so a not-yet-created destination inside the
150		// repository is refused before any symlink is followed.
151		if isWithin(resolvedRoot, absOut) {
152			return "", 0, nil, fmt.Errorf("output %q is inside the repository", output)
153		}
154		// Resolve every symlink in the path so a destination that reaches into the
155		// repository through a symlinked parent cannot hide.
156		resolved, err := filepath.EvalSymlinks(absOut)
157		if err != nil {
158			if !errors.Is(err, os.ErrNotExist) {
159				return "", 0, nil, fmt.Errorf("output %q: cannot resolve path: %w", output, err)
160			}
161			// The final component may simply not exist yet; its parent must.
162			parent := filepath.Dir(absOut)
163			resolvedParent, err := filepath.EvalSymlinks(parent)
164			if err != nil {
165				return "", 0, nil, fmt.Errorf("output %q: parent directory is not accessible: %w", output, err)
166			}
167			resolved = filepath.Join(resolvedParent, filepath.Base(absOut))
168		}
169		if isWithin(resolvedRoot, resolved) {
170			return "", 0, nil, fmt.Errorf("output %q is inside the repository", output)
171		}
172	
173		// Open and pin the resolved parent directory. The output's parent must be a
174		// real, accessible directory; the descriptor is reused for the commit so a
175		// later swap of any path component (replacing the directory with a symlink
176		// to the repository, for example) cannot redirect the rename.
177		resolvedParent := filepath.Dir(resolved)
178		pin, err := pinDirectory(resolvedParent)
179		if err != nil {
180			return "", 0, nil, fmt.Errorf("output %q: parent directory is not accessible: %w", output, err)
181		}
182	
183		if err := s.checkOutputNotRepoHardlink(resolved, output); err != nil {
184			pin.Close()
185			return "", 0, nil, err
186		}
187		return resolved, mode, pin, nil
188	}
189	
190	// isWithin reports whether target is root itself or lies beneath root. Both
191	// arguments must be cleaned absolute paths; lexical containment here is exact
192	// (".." segments are real separators), so a sibling sharing a name prefix
193	// (e.g. /vault-backup next to /vault) is not considered inside.
194	func isWithin(root, target string) bool {
195		rel, err := filepath.Rel(root, target)
196		if err != nil {
197			return false
198		}
199		return rel == "." || (rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)))
200	}
201	
202	// pinDirectory opens a directory directly (O_NOFOLLOW refuses a terminal
203	// symlink) and returns a descriptor used both as the location anchor for *at
204	// operations and for fsync. It is immune to later renames or symlink
205	// replacements of the path it was opened on.
206	func pinDirectory(dir string) (*parentPin, error) {
207		fd, err := syscall.Open(dir, syscall.O_RDONLY|syscall.O_DIRECTORY|syscall.O_NOFOLLOW|syscall.O_CLOEXEC, 0)
208		if err != nil {
209			return nil, err
210		}
211		return &parentPin{f: os.NewFile(uintptr(fd), dir), path: dir}, nil
212	}
213	
214	// checkOutputNotRepoHardlink refuses an existing output that is a hard link to
215	// any repository file (the index, the lock, an object, or a snapshot record).
216	// Replacing such a link would rewrite the repository file's contents through
217	// the link. Every repository file identity must be readable; an unreadable
218	// directory or stat failure is reported rather than skipped.
219	func (s *Store) checkOutputNotRepoHardlink(absOut, output string) error {
220		info, err := os.Lstat(absOut)
221		if errors.Is(err, os.ErrNotExist) {
222			return nil
223		}
224		if err != nil {
225			return fmt.Errorf("output %q: cannot inspect path: %w", output, err)
226		}
227		outID, ok := fileIDOf(info)
228		if !ok {
229			return nil
230		}
231		ids, err := s.repoFileIDs()
232		if err != nil {
233			return fmt.Errorf("output %q: cannot verify it is not linked to a repository file: %w", output, err)
234		}
235		for id, repoPath := range ids {
236			if id == outID {
237				return fmt.Errorf("output %q is a hard link to repository file %q", output, repoPath)
238			}
239		}
240		return nil
241	}
242	
243	type fileID struct {
244		dev uint64
245		ino uint64
246	}
247	
248	func fileIDOf(info os.FileInfo) (fileID, bool) {
249		st, ok := info.Sys().(*syscall.Stat_t)
250		if !ok {
251			return fileID{}, false
252		}
253		return fileID{dev: uint64(st.Dev), ino: uint64(st.Ino)}, true
254	}
255	
256	// repoFileIDs collects the device/inode identity of every repository file an
257	// output must not be hard-linked to: the index, the lock, every content
258	// object (including unreferenced and temp-named ones, since replacing any file
259	// in the repository is forbidden), and every file under snapshots/. A
260	// directory that should be present but cannot be read is an error: protection
261	// must never silently narrow to the files that happened to be stat-able.
262	func (s *Store) repoFileIDs() (map[fileID]string, error) {
263		ids := map[fileID]string{}
264		// The index may legitimately be absent from a freshly initialized
265		// repository; the lock is created by the time an operation runs. Missing
266		// files simply contribute no identity.
267		if err := addIfExists(s.indexPath(), ids); err != nil {
268			return nil, err
269		}
270		if err := addIfExists(s.lockPath(), ids); err != nil {
271			return nil, err
272		}
273		objectsDir := filepath.Join(s.root, "objects")
274		if entries, err := os.ReadDir(objectsDir); err != nil {
275			if !errors.Is(err, os.ErrNotExist) {
276				return nil, fmt.Errorf("cannot read objects directory: %w", err)
277			}
278		} else {
279			for _, entry := range entries {
280				if err := addIfExists(filepath.Join(objectsDir, entry.Name()), ids); err != nil {
281					return nil, err
282				}
283			}
284		}
285		if err := filepath.WalkDir(s.snapshotsDir(), func(path string, d fs.DirEntry, err error) error {
286			if err != nil {
287				if errors.Is(err, os.ErrNotExist) {
288					return nil
289				}
290				return err
291			}
292			if d.IsDir() {
293				return nil
294			}
295			return addIfExists(path, ids)
296		}); err != nil {
297			return nil, err
298		}
299		return ids, nil
300	}
301	
302	// addIfExists records the identity of an existing file, ignoring only a
303	// genuinely missing path.
304	func addIfExists(path string, ids map[fileID]string) error {
305		info, err := os.Lstat(path)
306		if errors.Is(err, os.ErrNotExist) {
307			return nil
308		}
309		if err != nil {
310			return err
311		}
312		if id, ok := fileIDOf(info); ok {
313			ids[id] = path
314		}
315		return nil
316	}
317	
318	// downloadObject streams the verified object into a temporary file beside the
319	// output and renames it into place only after the complete bytes match the
320	// record. It never truncates or writes the output directly, and it never
321	// buffers the whole object in memory.
322	func (s *Store) downloadObject(entry Entry, absOut string, mode os.FileMode, pin *parentPin) error {
323		objPath := s.objectPath(entry.Digest)
324		info, err := os.Lstat(objPath)
325		if err != nil {
326			if errors.Is(err, os.ErrNotExist) {
327				return fmt.Errorf("object %s is missing", entry.Digest)
328			}
329			return fmt.Errorf("cannot stat object %s: %w", entry.Digest, err)
330		}
331		if info.Mode()&os.ModeSymlink != 0 {
332			return fmt.Errorf("object %s is a symbolic link", entry.Digest)
333		}
334		if !info.Mode().IsRegular() {
335			return fmt.Errorf("object %s is not a regular file", entry.Digest)
336		}
337	
338		in, err := os.Open(objPath)
339		if err != nil {
340			return fmt.Errorf("cannot read object %s: %w", entry.Digest, err)
341		}
342		defer in.Close()
343	
344		// The temporary file is created through the pinned parent descriptor; even
345		// if a path component is replaced by a symlink while the copy runs, the
346		// descriptor stays attached to the original directory, the temporary bytes
347		// land there and nowhere else, and the final rename is performed through
348		// the pin rather than the path.
349		tmp, tmpBase, err := createTempIn(pin, ".download-")
350		if err != nil {
351			return fmt.Errorf("cannot create temporary file for output: %w", err)
352		}
353		committed := false
354		defer func() {
355			if !committed {
356				removeTempIn(pin, tmpBase)
357			}
358		}()
359	
360		if err := tmp.Chmod(mode); err != nil {
361			tmp.Close()
362			return fmt.Errorf("cannot prepare output file: %w", err)
363		}
364		hash := sha256.New()
365		n, copyErr := io.Copy(io.MultiWriter(tmp, hash), in)
366		readErr := in.Close()
367		if copyErr != nil {
368			tmp.Close()
369			return fmt.Errorf("cannot read object %s: %w", entry.Digest, copyErr)
370		}
371		if readErr != nil {
372			tmp.Close()
373			return fmt.Errorf("cannot read object %s: %w", entry.Digest, readErr)
374		}
375		if n != entry.Size {
376			tmp.Close()
377			return fmt.Errorf("object %s is corrupted: content is %d bytes, record says %d", entry.Digest, n, entry.Size)
378		}
379		if actual := hex.EncodeToString(hash.Sum(nil)); actual != entry.Digest {
380			tmp.Close()
381			return fmt.Errorf("object %s is corrupted: content checksum is %s, want %s", entry.Digest, actual, entry.Digest)
382		}
383		if err := tmp.Sync(); err != nil {
384			tmp.Close()
385			return fmt.Errorf("cannot write output %q: %w", absOut, err)
386		}
387		if err := tmp.Close(); err != nil {
388			return fmt.Errorf("cannot write output %q: %w", absOut, err)
389		}
390		if err := s.commitOutput(pin, tmpBase, absOut); err != nil {
391			return err
392		}
393		committed = true
394		// Best-effort directory sync so the rename survives a crash; failure here
395		// does not undo an already atomic replacement.
396		_ = syncDirectory(pin.f)
397		return nil
398	}
399	
400	// commitOutput atomically replaces absOut with tmpPath through the pinned
401	// parent directory descriptor. Immediately before the rename it revalidates
402	// everything established by checkOutputSafe, since another process may have
403	// changed the filesystem while the content was being prepared:
404	//
405	//   - the pinned directory must still be the same physical directory reached
406	//     by its (fully resolved) path, must still be outside the repository, and
407	//     no path component may have become a symlink;
408	//   - an existing destination must still be missing or a regular file;
409	//   - an existing destination must still not be a hard link to any repository
410	//     file.
411	//
412	// If any condition no longer holds the rename is refused, so a parent swapped
413	// for a symlink into the repository can never cause the package to land on an
414	// index, snapshot, lock, or object.
415	func (s *Store) commitOutput(pin *parentPin, tmpPath, absOut string) error {
416		if err := s.pinStillPointsOutsideRepo(pin, absOut); err != nil {
417			return err
418		}
419		base := filepath.Base(absOut)
420		var st syscall.Stat_t
421		if err := fstatatNoFollow(pin.f.Fd(), base, &st); err != nil {
422			if !errors.Is(err, os.ErrNotExist) {
423				return fmt.Errorf("output %q: cannot inspect destination: %w", absOut, err)
424			}
425		} else {
426			switch st.Mode & syscall.S_IFMT {
427			case syscall.S_IFLNK:
428				return fmt.Errorf("output %q is a symbolic link", absOut)
429			case syscall.S_IFREG:
430			default:
431				return fmt.Errorf("output %q is not a regular file", absOut)
432			}
433			outID := fileID{dev: uint64(st.Dev), ino: uint64(st.Ino)}
434			ids, err := s.repoFileIDs()
435			if err != nil {
436				return fmt.Errorf("output %q: cannot verify it is not linked to a repository file: %w", absOut, err)
437			}
438			for id, repoPath := range ids {
439				if id == outID {
440					return fmt.Errorf("output %q is a hard link to repository file %q", absOut, repoPath)
441				}
442			}
443		}
444	
445		if err := renameAt(pin.f.Fd(), filepath.Base(tmpPath), pin.f.Fd(), base); err != nil {
446			return fmt.Errorf("cannot write output %q: %w", absOut, err)
447		}
448		return nil
449	}
450	
451	// pinStillPointsOutsideRepo revalidates the pinned output directory at commit
452	// time. It must remain the exact directory the pin was opened on (compared by
453	// device/inode), its path must still resolve with no symlink components to the
454	// same physical directory, and that directory must still lie outside the
455	// resolved repository tree.
456	func (s *Store) pinStillPointsOutsideRepo(pin *parentPin, absOut string) error {
457		var pinStat syscall.Stat_t
458		if err := syscall.Fstat(int(pin.f.Fd()), &pinStat); err != nil {
459			return fmt.Errorf("output %q: cannot verify destination directory: %w", absOut, err)
460		}
461		info, err := os.Lstat(pin.path)
462		if err != nil {
463			return fmt.Errorf("output %q: destination directory is no longer accessible: %w", absOut, err)
464		}
465		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
466			return fmt.Errorf("output %q is unsafe: destination directory was replaced", absOut)
467		}
468		if id, ok := fileIDOf(info); !ok || id.dev != uint64(pinStat.Dev) || id.ino != uint64(pinStat.Ino) {
469			return fmt.Errorf("output %q is unsafe: destination directory was replaced", absOut)
470		}
471		resolved, err := filepath.EvalSymlinks(pin.path)
472		if err != nil {
473			return fmt.Errorf("output %q: destination directory is no longer accessible: %w", absOut, err)
474		}
475		if resolved != pin.path {
476			return fmt.Errorf("output %q is unsafe: destination directory now resolves through a symbolic link", absOut)
477		}
478		absRoot, err := filepath.Abs(s.root)
479		if err != nil {
480			return fmt.Errorf("cannot resolve repository root: %w", err)
481		}
482		resolvedRoot, err := filepath.EvalSymlinks(absRoot)
483		if err != nil {
484			return fmt.Errorf("cannot resolve repository root: %w", err)
485		}
486		if isWithin(resolvedRoot, pin.path) {
487			return fmt.Errorf("output %q is unsafe: destination directory is inside the repository", absOut)
488		}
489		return nil
490	}
491	
492	// atSymlinkNoFollow is the AT_SYMLINK_NOFOLLOW flag for fstatat.
493	const atSymlinkNoFollow = 0x100
494	
495	// fstatatNoFollow stats a path relative to dirfd without following a terminal
496	// symlink. A missing file is reported with os.ErrNotExist.
497	func fstatatNoFollow(dirfd uintptr, name string, st *syscall.Stat_t) error {
498		pathPtr, err := syscall.BytePtrFromString(name)
499		if err != nil {
500			return err
501		}
502		_, _, errno := syscall.Syscall6(syscall.SYS_FSTATAT, dirfd, uintptr(unsafe.Pointer(pathPtr)),
503			uintptr(unsafe.Pointer(st)), uintptr(atSymlinkNoFollow), 0, 0)
504		if errno != 0 {
505			if errno == syscall.ENOENT {
506				return os.ErrNotExist
507			}
508			return errno
509		}
510		return nil
511	}
512	
513	// renameAt renames within directories given by file descriptors, so the
514	// operation cannot be redirected by a later path-component replacement.
515	func renameAt(oldDir uintptr, oldName string, newDir uintptr, newName string) error {
516		oldPtr, err := syscall.BytePtrFromString(oldName)
517		if err != nil {
518			return err
519		}
520		newPtr, err := syscall.BytePtrFromString(newName)
521		if err != nil {
522			return err
523		}
524		_, _, errno := syscall.Syscall6(syscall.SYS_RENAMEAT,
525			oldDir, uintptr(unsafe.Pointer(oldPtr)),
526			newDir, uintptr(unsafe.Pointer(newPtr)), 0, 0)
527		if errno != 0 {
528			return errno
529		}
530		return nil
531	}
532	
533	// createTempIn creates a new, exclusively owned temporary file with a unique
534	// name directly inside the pinned directory (via openat, never by path) and
535	// returns the open file together with its basename for the commit rename.
536	func createTempIn(pin *parentPin, prefix string) (*os.File, string, error) {
537		var random [16]byte
538		if _, err := rand.Read(random[:]); err != nil {
539			return nil, "", err
540		}
541		for i := 0; i < 100; i++ {
542			if i > 0 {
543				if _, err := rand.Read(random[:]); err != nil {
544					return nil, "", err
545				}
546			}
547			name := prefix + hex.EncodeToString(random[:])
548			fd, errno := syscall.Openat(int(pin.f.Fd()), name,
549				syscall.O_CREAT|syscall.O_EXCL|syscall.O_WRONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0o600)
550			if errno == syscall.EEXIST {
551				continue
552			}
553			if errno != nil {
554				return nil, "", errno
555			}
556			return os.NewFile(uintptr(fd), filepath.Join(pin.path, name)), name, nil
557		}
558		return nil, "", errors.New("could not find an unused temporary file name")
559	}
560	
561	// removeTempIn unlinks a staged temporary file through the pinned directory.
562	func removeTempIn(pin *parentPin, name string) {
563		namePtr, err := syscall.BytePtrFromString(name)
564		if err != nil {
565			return
566		}
567		_, _, _ = syscall.Syscall6(syscall.SYS_UNLINKAT, pin.f.Fd(),
568			uintptr(unsafe.Pointer(namePtr)), 0, 0, 0, 0)
569	}
570	
571	func syncDirectory(dir *os.File) error {
572		return dir.Sync()
573	}
574

